#import <Foundation/Foundation.h>
#import <Metal/Metal.h>
int main(int argc,char**argv){@autoreleasepool{
 if(argc!=2)return 2;NSString*out=@(argv[1]);[[NSFileManager defaultManager]createDirectoryAtPath:out withIntermediateDirectories:YES attributes:nil error:NULL];
 NSString*src=@"#include <metal_stdlib>\nusing namespace metal;kernel void table(device const half2*p[[buffer(0)]],device half4*q[[buffer(1)]],uint i[[thread_position_in_grid]]){half a=p[i].x,b=p[i].y;q[i]=half4(atan2(a,b),atan2(-a,b),atan2(a,-b),atan2(-a,-b));}\n";
 id<MTLDevice>d=MTLCreateSystemDefaultDevice();NSError*error=nil;MTLCompileOptions*o=[MTLCompileOptions new];o.fastMathEnabled=YES;id<MTLLibrary>lib=[d newLibraryWithSource:src options:o error:&error];if(!lib){[error.description writeToFile:[out stringByAppendingPathComponent:@"error.txt"]atomically:YES encoding:NSUTF8StringEncoding error:NULL];return 3;}id<MTLComputePipelineState>ps=[d newComputePipelineStateWithFunction:[lib newFunctionWithName:@"table"]error:&error];if(!ps)return 4;
 NSUInteger n=1024*1024;id<MTLBuffer>ib=[d newBufferWithLength:n*4 options:MTLResourceStorageModeShared],ob=[d newBufferWithLength:n*8 options:MTLResourceStorageModeShared];id<MTLCommandQueue>queue=[d newCommandQueue];NSString*file=[out stringByAppendingPathComponent:@"atan2-canonical.f16"];[[NSFileManager defaultManager]createFileAtPath:file contents:nil attributes:nil];NSFileHandle*handle=[NSFileHandle fileHandleForWritingAtPath:file];NSMutableArray*rows=[NSMutableArray new];
 for(int delta=-29;delta<=29;delta++){@autoreleasepool{int eb=-(int)floor(delta/2.0),ea=delta+eb;uint16_t*p=ib.contents;for(NSUInteger i=0;i<n;i++){p[i*2]=((ea+15)<<10)|(i>>10);p[i*2+1]=((eb+15)<<10)|(i&1023);}id<MTLCommandBuffer>cb=[queue commandBuffer];id<MTLComputeCommandEncoder>e=[cb computeCommandEncoder];[e setComputePipelineState:ps];[e setBuffer:ib offset:0 atIndex:0];[e setBuffer:ob offset:0 atIndex:1];[e dispatchThreads:MTLSizeMake(n,1,1)threadsPerThreadgroup:MTLSizeMake(128,1,1)];[e endEncoding];[cb commit];[cb waitUntilCompleted];if(cb.error)return 5;[handle writeData:[NSData dataWithBytesNoCopy:ob.contents length:ob.length freeWhenDone:NO]];[rows addObject:@{@"delta_exponent":@(delta),@"a_exponent":@(ea),@"b_exponent":@(eb)}];}}
 [handle closeFile];NSDictionary*m=@{@"source":src,@"os":NSProcessInfo.processInfo.operatingSystemVersionString,@"device":d.name,@"dtype":@"<f2",@"shape":@[@59,@1024,@1024,@4],@"quadrants":@[@"+a,+b",@"-a,+b",@"+a,-b",@"-a,-b"],@"rows":rows,@"scope":@"Numerical table for canonical normal half inputs. Common power-of-two scaling is a hypothesis outside independently validated controls. Subnormal, zero and exponent-difference tails require explicit handling."};[[NSJSONSerialization dataWithJSONObject:m options:NSJSONWritingPrettyPrinted error:NULL]writeToFile:[out stringByAppendingPathComponent:@"metadata.json"]atomically:YES];return 0;
